// DATA CONTOH: 110 soal dari bank D'Ajiks (TWK bank 100 no 1-30, TIU Paket 1, TKP Paket 1). Tanpa kunci. Dibuat oleh build-to.cjs.
var SOAL = [{"s":"TWK","t":"Anda anggota tim penyusun rancangan peraturan bupati tentang bantuan usaha mikro. Bagian hukum meminta setiap tahapan penyusunan selesai tepat waktu, sementara Indikator Nilai Pancasila dari BPIP harus dipakai untuk menilai isi rancangan. Langkah yang paling tepat sesuai fungsi indikator tersebut dalam pembentukan kebijakan adalah...","o":{"A":"Menguji isi setiap pasal memakai ukuran tiap sila dalam jadwal tim.","B":"Memenuhi setiap tahapan penyusunan tepat waktu sesuai daftar periksa dari bagian hukum.","C":"Mengukur kenaikan omzet usaha mikro penerima sesudah bantuan berjalan selama setahun.","D":"Mengundang perwakilan pelaku usaha mikro untuk memberi masukan atas draf peraturan bupati.","E":"Mencantumkan kutipan sila-sila Pancasila pada bagian konsiderans rancangan peraturan bupati."}},{"s":"TWK","t":"Kelompok penghayat kepercayaan meminta jatah ruang serbaguna kampus untuk kegiatan rutin, sedangkan kelompok agama lain yang berbagi ruang meminta jaminan tidak ada ceramah yang merendahkan ajaran pengguna lain. Panitia kemudian menyusun jadwal bergilir dan tata tertib saling menghormati. Nilai yang paling tepat menjelaskan keputusan panitia berdasarkan indikator sila pertama dan kedua adalah...","o":{"A":"Kepatuhan, karena panitia menjalankan tata tertib fasilitas kampus secara konsisten.","B":"Netralitas, karena panitia tidak memihak kelompok mana pun dalam pembagian ruang.","C":"Toleransi berkeadaban, karena hak berkeyakinan dijalankan dengan menjaga martabat pemeluk lain.","D":"Kesetaraan akses, karena setiap kelompok memperoleh jatah ruang dengan durasi sama.","E":"Solidaritas sosial, karena para pengguna ruang bergantian membantu merawat fasilitas bersama."}},{"s":"TWK","t":"Dalam Sidang Pertama BPUPK, 29 Mei sampai 1 Juni 1945, para anggota menyampaikan usulan dasar negara yang berbeda-beda, lalu perumusan dilanjutkan untuk mencari kesepakatan bersama. Kini forum pemuda lintas organisasi di sebuah kabupaten harus menyepakati satu sikap bersama tentang program kepemudaan daerah. Penerapan yang paling mencerminkan teladan sidang tersebut dalam forum itu adalah...","o":{"A":"Menyelenggarakan diskusi sejarah tentang ragam pidato anggota BPUPK bagi peserta forum.","B":"Menyampaikan usulan organisasi secara rinci sambil mencatat keberatan pihak lain.","C":"Menjaga suasana forum tetap akrab agar hubungan antarorganisasi tidak renggang.","D":"Menetapkan sikap bersama berdasarkan usulan yang paling banyak didukung organisasi.","E":"Mengajukan gagasan dengan alasan terbuka sambil merumuskan titik temu antarorganisasi."}},{"s":"TWK","t":"Guru TIK sebuah SMA mengusulkan aplikasi pembelajaran buatan luar negeri karena fiturnya interaktif, sementara guru PPKn meminta materi tetap sesuai tujuan pendidikan kebangsaan. Kepala sekolah harus memutuskan dalam rapat pekan ini. Sikap yang paling tepat bagi kepala sekolah berdasarkan kedudukan Pancasila sebagai ideologi terbuka adalah...","o":{"A":"Memakai materi sesuai tujuan pendidikan kebangsaan tanpa mengaktifkan fitur interaktif aplikasi.","B":"Memakai keunggulan teknologinya sambil memilah isi yang sejalan dengan nilai dasar bangsa.","C":"Menunda pemakaian sampai sekolah memiliki aplikasi buatan dalam negeri yang setara.","D":"Mengadopsi aplikasi itu lalu menambahkan slogan kebangsaan pada halaman pembukanya.","E":"Mengikuti fitur dan isi bawaan aplikasi apa adanya agar siswa akrab standar global."}},{"s":"TWK","t":"Pengurus sebuah organisasi kepemudaan rutin membacakan Pancasila sebelum rapat, tetapi keputusan rapat jarang memperhitungkan anggota penyandang disabilitas. Menurut pedoman BPIP, ideologi bukan sekadar gagasan yang dipahami, melainkan praktik yang tampak dalam keputusan. Alasan yang paling mendasar untuk memperbaiki kebiasaan organisasi tersebut adalah...","o":{"A":"Pembacaan Pancasila sebelum rapat menumbuhkan pemahaman gagasan dasar bagi setiap anggota.","B":"Kegiatan pembukaan rapat menjaga identitas organisasi tetap dikenal oleh anggota baru.","C":"Anggota penyandang disabilitas akan lebih aktif bila kebutuhannya diperhitungkan sejak awal.","D":"Nilai hidup bersama baru bermakna ketika mengarahkan perlakuan nyata kepada sesama.","E":"Organisasi kepemudaan perlu menghormati hak penyandang disabilitas yang dijamin undang-undang."}},{"s":"TWK","t":"Pemerintah desa menetapkan dua sasaran program kerukunan tahun ini: warga dapat beribadah dengan aman, dan warga berbeda keyakinan tetap saling menghormati. Tim desa mengusulkan empat langkah, yaitu (1) menyediakan ruang ibadah, (2) membagi jadwal pemakaian secara setara, (3) membentuk forum lintas iman, dan (4) mencatat kehadiran jemaah setiap kelompok. Pasangan langkah yang paling tepat memenuhi kedua sasaran berdasarkan indikator sila pertama adalah...","o":{"A":"Langkah pertama dan kedua, karena keduanya membuat warga dapat beribadah dengan aman.","B":"Langkah kedua dan keempat, karena keduanya membuat pengelolaan kegiatan ibadah tertib dan tercatat.","C":"Langkah pertama dan keempat, karena keduanya memastikan ibadah berlangsung tertib setiap pekan.","D":"Langkah pertama dan ketiga, karena keduanya menyediakan sarana beribadah dan membina hubungan antarumat.","E":"Langkah ketiga dan keempat, karena keduanya menghasilkan laporan kerukunan yang dapat dipantau."}},{"s":"TWK","t":"Pemerintah daerah membuka pelatihan kerja dengan syarat yang sama bagi semua warga, tetapi warga tunarungu dan warga pulau terluar sulit mengikutinya. Keadilan kebijakan tidak hanya mengakui derajat setiap warga, tetapi juga mengatasi hambatan akses yang berbeda-beda. Hubungan sila kedua dan sila kelima dalam kasus tersebut paling tepat dipahami sebagai...","o":{"A":"Pengakuan derajat setiap warga menghasilkan pembagian manfaat program secara merata.","B":"Penghormatan martabat manusia mendasari perluasan kesempatan bagi warga yang terhambat.","C":"Pemerataan kesempatan kerja membentuk penghormatan terhadap perbedaan latar sosial warga.","D":"Pengakuan hak warga menjaga ketertiban pelaksanaan program bantuan daerah secara konsisten.","E":"Penghormatan martabat manusia menuntut syarat pelatihan yang sama bagi setiap warga."}},{"s":"TWK","t":"Motif tenun sebuah desa biasa dipakai dalam upacara adat setempat. Sebuah usaha rintisan ingin memakai motif itu untuk produk digital yang mengikuti selera pasar, sementara para penenun sepuh meminta makna motif tidak diubah sembarangan. Sikap yang paling tepat bagi usaha rintisan itu berdasarkan indikator sila ketiga tentang pengembangan kebudayaan adalah...","o":{"A":"Merancang desain baru bersama pemilik tradisi dengan batas pakem yang disepakati.","B":"Mempertahankan pola lama sambil menunda pemasaran sampai tren pasar berubah.","C":"Mengikuti selera pasar lalu mencantumkan asal motif desa pada kemasan.","D":"Membayar royalti kepada desa sebagai imbalan atas pemakaian motif tenun.","E":"Menampilkan cerita asal-usul motif pada laman toko daring sebagai bahan promosi."}},{"s":"TWK","t":"Panitia khusus DPRD sebuah kota menyusun rancangan peraturan daerah tentang penataan ruang publik. Kedudukan Pancasila sebagai norma dasar dalam Pembukaan UUD NRI Tahun 1945 bukan sekadar rumusan yang dikutip, melainkan ukuran bagi isi setiap peraturan yang dibentuk kemudian. Langkah panitia yang paling tepat sesuai kedudukan tersebut adalah...","o":{"A":"Mengutip rumusan Pancasila dalam Pembukaan UUD pada bagian pengantar naskah.","B":"Menguji keselarasan pasal-pasal raperda terhadap dasar tertinggi sebelum disahkan.","C":"Menyosialisasikan peraturan baru kepada warga setelah disahkan oleh dewan.","D":"Membandingkan rancangan dengan peraturan daerah lain yang mengatur topik serupa.","E":"Menyelenggarakan seremoni peluncuran peraturan dalam acara resmi pemerintah daerah."}},{"s":"TWK","t":"Pada masa reses dan Sidang Kedua BPUPK, 10 sampai 17 Juli 1945, usulan yang berbeda dibahas lanjut hingga menjadi rancangan undang-undang dasar. Kini OSIS sebuah sekolah menerima usulan aturan kelas dari tiap angkatan yang isinya saling berlainan. Penerapan yang paling mencerminkan proses BPUPK tersebut bagi OSIS adalah...","o":{"A":"Merekam setiap usulan secara rinci agar riwayat perdebatan tersimpan untuk arsip.","B":"Memberi waktu tiap angkatan mempertajam usulannya sebelum dibahas dalam rapat pleno.","C":"Menguji tiap gagasan yang bertentangan lalu merangkainya dalam satu naskah tertulis.","D":"Memilih usulan angkatan yang paling banyak pendukungnya lalu menetapkannya sebagai aturan.","E":"Menghormati usulan setiap angkatan dengan tetap memberlakukan aturan kelas masing-masing."}},{"s":"TWK","t":"Dua sekolah dari provinsi berbeda merancang festival budaya bersama bagi siswanya. Sekolah pertama ingin setiap daerah tampil dengan tradisinya yang khas, sedangkan sekolah kedua ingin festival menumbuhkan rasa satu bangsa di antara peserta. Makna persatuan berdasarkan sila ketiga paling tepat terlihat pada rancangan...","o":{"A":"Kompetisi budaya terbuka yang mendorong peserta meningkatkan mutu pertunjukan daerahnya.","B":"Perayaan bergilir yang memberi tiap daerah panggung menonjolkan tradisinya yang khas.","C":"Pertemuan ragam karya daerah yang diarahkan pada kebanggaan sebagai warga Indonesia.","D":"Kolaborasi lintas daerah yang meleburkan tarian daerah menjadi satu karya baru.","E":"Pameran tradisi yang menambah pengetahuan peserta tentang keragaman budaya Nusantara."}},{"s":"TWK","t":"Pemerintah provinsi membangun platform belanja daring untuk usaha kecil. Dinas perdagangan menargetkan nilai transaksi naik tahun ini, sementara Pasal 33 ayat (4) UUD NRI Tahun 1945 menghendaki perekonomian berdasar demokrasi ekonomi dengan prinsip kebersamaan dan efisiensi berkeadilan. Kebijakan platform yang paling tepat sesuai prinsip demokrasi ekonomi adalah...","o":{"A":"Membuka platform bagi pelaku terdaftar dengan biaya layanan seragam dan transparan.","B":"Memberi promosi bergilir sambil menyerahkan dukungan teknis pada mekanisme pasar.","C":"Menyediakan etalase khusus produk daerah tanpa program pendampingan bagi pelaku usaha.","D":"Mengutamakan kenaikan jumlah transaksi sambil menunda evaluasi jangkauan pelaku kecil.","E":"Memadukan kanal penjualan dengan pelatihan dan modal bagi pelaku yang tertinggal."}},{"s":"TWK","t":"Rapat warga sebuah kelurahan memilih program lingkungan setelah mendengar kebutuhan kelompok nelayan, petani, dan pedagang. Demokrasi Pancasila tidak hanya memberi ruang suara rakyat, tetapi juga mengarahkan keputusan menuju kesejahteraan bersama. Alasan yang paling mendasar bagi cara musyawarah tersebut berdasarkan sila keempat adalah...","o":{"A":"Suara terbanyak warga menjadi dasar sah bagi setiap keputusan program.","B":"Pembagian waktu bicara membantu rapat berlangsung tertib dan mudah dicatat.","C":"Kehadiran kelompok beragam meningkatkan penerimaan sosial terhadap hasil rapat.","D":"Kedaulatan publik dijalankan melalui hikmat kebijaksanaan demi keadilan sosial.","E":"Kesepakatan warga mengurangi kemungkinan penolakan saat program mulai dilaksanakan."}},{"s":"TWK","t":"Bappeda sebuah kabupaten menyusun program prioritas dengan lima sasaran: (1) pendidikan, (2) kesehatan, (3) kesempatan usaha, (4) perlindungan lingkungan, dan (5) publikasi capaian. Dokumen perencanaan meminta program memperluas kesempatan hidup layak warga dan menjaga kemajuan ekonomi tetap berkelanjutan. Kombinasi sasaran yang paling tepat memenuhi kedua ketentuan itu berdasarkan indikator sila kelima adalah...","o":{"A":"Sasaran ketiga dan keempat, karena keduanya memadukan peluang usaha dengan kelestarian alam.","B":"Sasaran pertama dan kedua, karena keduanya memenuhi layanan dasar keluarga yang membutuhkan.","C":"Sasaran kedua dan kelima, karena keduanya menaikkan kepercayaan warga pada capaian program.","D":"Sasaran keempat dan kelima, karena keduanya menjaga lingkungan dan melaporkannya secara terbuka.","E":"Sasaran pertama dan ketiga, karena keduanya memperluas kesempatan hidup layak bagi warga."}},{"s":"TWK","t":"Dalam pidato 1 Juni 1945 di depan BPUPK, Sukarno mengusulkan lima prinsip sebagai dasar bagi negara yang akan dibentuk. Kini tim penyusun rencana pembangunan sebuah desa ingin menjadikan peristiwa itu teladan dalam pekerjaannya, bukan hanya bahan peringatan. Penerapan yang paling mencerminkan makna pidato tersebut bagi tim adalah...","o":{"A":"Menumbuhkan kebanggaan warga desa terhadap sejarah lahirnya Pancasila setiap bulan Juni.","B":"Menilai setiap usulan program desa memakai ukuran kelima sila sebelum ditetapkan.","C":"Mengarsipkan salinan pidato 1 Juni 1945 di perpustakaan desa untuk dipelajari warga.","D":"Memakai prinsip kebangsaan dari pidato itu sebagai tema utama rencana desa.","E":"Mengkaji perbedaan rumusan sila antara pidato 1 Juni dan Pembukaan UUD."}},{"s":"TWK","t":"Seorang siswa menyamakan Pancasila dengan UUD NRI Tahun 1945 karena keduanya sama-sama menjadi rujukan kehidupan bernegara. Hubungan keduanya tidak hanya soal urutan norma, tetapi juga perbedaan fungsi antara nilai dasar dan aturan dasar. Untuk meluruskan pemahaman siswa itu, hubungan Pancasila dan UUD NRI Tahun 1945 paling tepat dipahami sebagai...","o":{"A":"Konstitusi mengikat penyelenggaraan negara melalui aturan mengenai lembaga, kekuasaan, dan hak warga.","B":"Nilai Pancasila mendasari perumusan norma konstitusional dalam UUD NRI Tahun 1945.","C":"Pancasila mempersatukan bangsa, sedangkan konstitusi membatasi kekuasaan lembaga negara secara hukum.","D":"Konstitusi menjabarkan tujuan negara, sedangkan Pancasila membimbing perilaku masyarakat sehari-hari.","E":"Pancasila menjadi ideologi negara, sedangkan konstitusi menjadi dokumen hukum tertinggi nasional."}},{"s":"TWK","t":"Ketua RT mengajak warga merenovasi pos ronda yang rusak menjelang musim hujan. Sebagian warga ingin kerja bakti cukup sehari agar cepat selesai, sementara warga lain mengingatkan bahwa pos lama rusak karena tidak ada yang merawatnya setelah dibangun. Wujud gotong royong yang paling tepat menurut asas kerja dan tanggung jawab bersama adalah...","o":{"A":"Mengumpulkan warga pada akhir pekan untuk merenovasi pos ronda dalam sehari.","B":"Menjadwalkan giliran perawatan pos ronda setelah warga merampungkan renovasinya.","C":"Merasakan kedekatan antarwarga setelah renovasi pos ronda selesai dikerjakan.","D":"Menyumbangkan dana material untuk mendukung renovasi pos ronda RT.","E":"Mengadakan syukuran kecil begitu renovasi pos ronda dinyatakan selesai."}},{"s":"TWK","t":"Balai desa dipakai bergantian oleh kelompok pengajian, persekutuan doa, dan penghayat kepercayaan. Kelompok yang lebih besar meminta jam tetap setiap pekan, sedangkan kelompok kecil meminta jadwal yang tidak terus kalah oleh kelompok besar. Pengaturan yang paling tepat dilakukan pemerintah desa berdasarkan indikator sila pertama adalah...","o":{"A":"Memberikan jadwal menurut urutan permohonan tanpa koordinasi antarkelompok pengguna.","B":"Membagi waktu secara sama sambil menyerahkan benturan jadwal kepada pengguna.","C":"Menyusun alokasi transparan melalui dialog pengguna dan kesepakatan tata bersama.","D":"Mendahulukan kelompok terbesar lalu menyediakan waktu pengganti bagi kelompok lain.","E":"Mengikuti kebiasaan pengelola balai dalam menyusun jadwal kegiatan keagamaan."}},{"s":"TWK","t":"Pada Sidang Kedua BPUPK, pembahasan rancangan negara mencakup bentuk negara, wilayah, ekonomi, hingga pendidikan, dan setiap bidang ditimbang demi negara yang akan dibentuk. Kini Anda menjadi perwakilan dinas dalam forum penyusunan rencana pembangunan kabupaten yang membahas banyak sektor sekaligus. Sikap yang paling mencerminkan keteladanan sidang tersebut adalah...","o":{"A":"Memperluas agenda forum agar setiap sektor memperoleh waktu pembahasan tersendiri.","B":"Mendokumentasikan pandangan peserta supaya alasan setiap usulan dapat ditelusuri kembali.","C":"Menjaga forum berjalan lancar agar rencana pembangunan selesai sesuai jadwal.","D":"Memperjuangkan mandat dinas sendiri sambil menghormati tata tertib forum yang disepakati.","E":"Membandingkan usulan antarbidang lalu mendahulukan pilihan bagi kemaslahatan bersama."}},{"s":"TWK","t":"Panitia beasiswa daerah memegang dua ketentuan: syarat akademik sama untuk semua pelamar, dan pendaftaran harus terjangkau oleh warga di setiap wilayah. Pelamar dari pulau terpencil kesulitan karena pendaftaran hanya dibuka secara daring, sedangkan sinyal internet di sana lemah. Kebijakan yang paling tepat mencerminkan keadilan berdasarkan indikator sila kedua dan kelima adalah...","o":{"A":"Menyediakan jalur luring sambil mempertahankan ukuran kelayakan yang sebanding.","B":"Memperpanjang tenggat bagi pendaftar yang mengajukan permohonan melalui sekolah asal.","C":"Menurunkan syarat akademik bagi pelamar dari wilayah dengan jaringan terbatas.","D":"Menyediakan bantuan teknis daring sambil mempertahankan satu kanal pendaftaran resmi.","E":"Membagi kuota wilayah berdasarkan jumlah sekolah yang mengikuti program beasiswa."}},{"s":"TWK","t":"Forum pemuda nasional menampilkan beragam bahasa daerah, musik, dan gagasan pembangunan dalam satu pertemuan. Pancasila sebagai kekuatan pemersatu bukan sekadar menerima keragaman, melainkan mengarahkannya pada cita-cita bersama sebagai bangsa. Makna fungsi pemersatu Pancasila yang paling mendasar terlihat pada...","o":{"A":"Panggung bersama yang menampilkan bahasa daerah, musik, dan gagasan pembangunan pemuda.","B":"Ruang perjumpaan yang mengurangi prasangka melalui percakapan antarkelompok pemuda secara terbuka.","C":"Jaringan kerja sama lintas organisasi daerah yang terus berlanjut setelah forum.","D":"Wadah ekspresi yang menjaga keberlanjutan identitas budaya tiap komunitas secara mandiri.","E":"Titik temu nilai yang menggerakkan komunitas majemuk menuju kemajuan Indonesia."}},{"s":"TWK","t":"Anda staf bagian hukum pemerintah kota yang menyusun rancangan aturan transportasi daring. Wali kota meminta rancangan selesai bulan ini, sementara indikator sila keempat menuntut aspirasi pengemudi, penumpang, dan pengusaha diolah secara bertanggung jawab. Mekanisme yang paling tepat sesuai indikator tersebut adalah...","o":{"A":"Menyelenggarakan konsultasi terjadwal, mempublikasikan tanggapan, lalu menjelaskan pilihan akhir.","B":"Membuka kolom masukan daring sambil menyerahkan pemilihan usulan kepada tim teknis.","C":"Mengadakan jajak pendapat cepat lalu mengambil pilihan dengan dukungan terbanyak.","D":"Mengundang perwakilan pengguna dan menetapkan keputusan sebelum tanggapan diterbitkan.","E":"Menggabungkan aspirasi publik dan kajian teknis tanpa menerangkan pertimbangan akhirnya."}},{"s":"TWK","t":"Dalam rapat anggota koperasi, sebagian anggota ingin usulan langsung diputuskan dengan suara terbanyak agar rapat cepat selesai, sementara anggota lain meminta alasan tiap usulan dibahas dulu. Ketua rapat sudah memberi waktu bicara yang sama kepada semua anggota. Ciri yang paling tepat membedakan musyawarah dari pemungutan suara menurut indikator sila keempat adalah...","o":{"A":"Kesetaraan durasi bicara bagi anggota sebelum pilihan akhir dicatat panitia rapat.","B":"Pengolahan pandangan menuju kesepakatan yang dilaksanakan dengan itikad baik.","C":"Penerimaan hasil mayoritas yang menjaga kelancaran program koperasi setelah rapat selesai.","D":"Pencatatan pendapat berbeda yang memberi bahan evaluasi untuk rapat koperasi berikutnya.","E":"Keteraturan prosedur rapat yang memastikan anggota memahami urutan pengambilan keputusan."}},{"s":"TWK","t":"Panitia peringatan Sumpah Pemuda tingkat kabupaten harus memilih dua dari lima kegiatan: (1) dokumentasi seni daerah, (2) pertukaran budaya antarsekolah, (3) aksi bantuan bencana lintas organisasi, (4) promosi organisasi masing-masing, dan (5) pemetaan kebutuhan pemuda nasional. Panduan kegiatan meminta pilihan yang menumbuhkan kebanggaan pada budaya daerah dan mendahulukan kepentingan bangsa di atas golongan. Pasangan kegiatan yang paling tepat memenuhi panduan itu berdasarkan indikator sila ketiga adalah...","o":{"A":"Kegiatan pertama dan keempat, karena keduanya memperkuat identitas kelompok asal secara mendalam.","B":"Kegiatan ketiga dan kelima, karena keduanya mengutamakan pelayanan kebutuhan nasional secara langsung.","C":"Kegiatan kedua dan ketiga, karena keduanya merawat keberagaman melalui kerja kebangsaan.","D":"Kegiatan pertama dan kedua, karena keduanya memperluas apresiasi budaya daerah antarpeserta.","E":"Kegiatan keempat dan kelima, karena keduanya menghubungkan kelompok dengan agenda nasional bersama."}},{"s":"TWK","t":"Rumusan dasar negara berkembang dari pidato-pidato Sidang Pertama BPUPK, Piagam Jakarta 22 Juni 1945, hingga rumusan dalam Pembukaan UUD NRI Tahun 1945 yang disahkan PPKI pada 18 Agustus 1945. Sepanjang proses itu, gagasan pokoknya dipertahankan, sedangkan rumusannya disempurnakan agar dapat diterima semua kelompok. Kini sebuah organisasi kemasyarakatan merevisi anggaran dasarnya karena anggotanya makin beragam. Penerapan yang paling mencerminkan pelajaran dari proses perumusan itu adalah...","o":{"A":"Mempertahankan rancangan awal anggaran dasar sebagai acuan tetap tanpa perubahan redaksi.","B":"Menyesuaikan isi anggaran dasar menurut tuntutan kelompok anggota yang paling besar.","C":"Memperpanjang masa pembahasan agar perbedaan kecil dipahami sebelum rapat memutuskan.","D":"Memegang tujuan dasar perkumpulan sambil menata redaksi lewat dialog antaranggota.","E":"Mencatat usulan anggota lalu menyerahkan penyelarasan akhir kepada ketua organisasi."}},{"s":"TWK","t":"Sebuah sekolah akan memakai aplikasi untuk menentukan siswa penerima bantuan belajar. Panduan program meminta dua hal berlaku bersama: bantuan harus tepat sasaran, dan siswa tidak boleh dipermalukan atau dirugikan oleh cara seleksinya. Tindakan pengurus yang paling tepat menunjukkan kedudukan Pancasila sebagai tolok ukur kebijakan dalam kasus itu adalah...","o":{"A":"Mengutamakan ketepatan sasaran dengan menambah jumlah data yang dinilai aplikasi.","B":"Memeriksa ulang hasil penilaian sistem dan merahasiakan nama siswa terpilih.","C":"Menjelaskan cara kerja aplikasi kepada orang tua dan meminta persetujuan tertulis.","D":"Mengukur kenaikan nilai belajar siswa penerima pada akhir semester berikutnya.","E":"Membuka layanan pengaduan bagi keluarga yang merasa dirugikan oleh hasil seleksi."}},{"s":"TWK","t":"Alinea keempat Pembukaan UUD 1945 merumuskan tujuan negara, antara lain memajukan kesejahteraan umum dan mencerdaskan kehidupan bangsa. Kini karang taruna sebuah kelurahan harus memilih beberapa usulan program karena dananya terbatas. Penerapan rumusan tujuan negara yang paling tepat dalam keputusan karang taruna itu adalah...","o":{"A":"Mengadakan diskusi warga untuk mengenalkan isi alinea keempat Pembukaan UUD 1945.","B":"Memilih usulan yang paling cepat selesai agar hasilnya segera terlihat.","C":"Mencantumkan kutipan tujuan negara pada proposal dan laporan setiap program.","D":"Memilih usulan yang paling banyak didukung suara anggota karang taruna.","E":"Menilai tiap rencana dari sumbangannya bagi taraf hidup dan pendidikan warga."}},{"s":"TWK","t":"OSIS menimbang enam kegiatan: (1) pameran budaya daerah, (2) forum dengar pendapat lintas kelas, (3) penanaman pohon, (4) penggalangan dana bencana, (5) pembagian fasilitas belajar menurut kebutuhan, dan (6) lomba kebersihan kelas. Pengamalan Pancasila di sekolah bukan sekadar membuat kegiatan yang bermanfaat, melainkan membuka suara warga sekolah dalam keputusan dan membagi manfaat secara adil. Pasangan kegiatan yang paling tepat mencerminkan pengamalan sila keempat dan kelima itu adalah...","o":{"A":"Kegiatan 1 dan 2, karena keduanya memberi tempat bagi keragaman warga sekolah.","B":"Kegiatan 3 dan 4, karena keduanya langsung memberi manfaat bagi orang banyak.","C":"Kegiatan 2 dan 5, karena siswa ikut bersuara dan yang kekurangan didahulukan.","D":"Kegiatan 1 dan 6, karena keduanya menumbuhkan kebanggaan dan disiplin warga sekolah.","E":"Kegiatan 4 dan 5, karena keduanya menyalurkan bantuan kepada pihak yang membutuhkan."}},{"s":"TWK","t":"Sebuah peraturan layanan disusun melalui prosedur resmi, tetapi persyaratannya ternyata menyulitkan warga penyandang disabilitas. Pancasila menuntut aturan tidak hanya sah prosedurnya, tetapi juga adil akibatnya bagi setiap warga. Berdasarkan sila kedua dan kelima, peninjauan ulang peraturan itu penting dilakukan karena...","o":{"A":"Prosedur resmi membuat lembaga mudah mempertanggungjawabkan aturan kepada publik.","B":"Masukan penyandang disabilitas perlu dihimpun sebelum aturan baru disusun kembali.","C":"Warga akan lebih percaya kepada lembaga bila keluhannya ditanggapi cepat.","D":"Suatu ketentuan layak ditaati bila cara membuatnya benar dan hasilnya setara.","E":"Aturan yang sah dan tertulis jelas memberi kepastian bagi petugas dan warga."}},{"s":"TWK","t":"Panitia kelas menyusun program layanan teman sebaya setelah membaca Pembukaan UUD 1945. Sebagian anggota ingin naskah itu dibacakan pada setiap pertemuan agar diingat, sementara anggota lain ingin isinya benar-benar memengaruhi bentuk program. Langkah yang paling tepat mencerminkan kedudukan Pembukaan sebagai pedoman bagi panitia adalah...","o":{"A":"Menurunkan sasaran kegiatan dari alinea keempat dan membahasnya dalam rapat kelas.","B":"Membacakan Pembukaan UUD 1945 pada awal setiap pertemuan rutin panitia kelas.","C":"Menumbuhkan rasa bangga anggota setelah mendengar naskah Pembukaan dibacakan.","D":"Mencatat poin penting Pembukaan dan menempelkannya di papan pengumuman kelas.","E":"Mengundang guru PPKn untuk menjelaskan isi Pembukaan kepada para siswa."}},{"s":"TIU","t":"Dinas perhubungan memasang lampu penerangan baru di Jalan Lingkar Timur. Jumlah kecelakaan pada malam hari di jalan itu turun dari 24 kejadian pada tahun sebelum pemasangan menjadi 9 kejadian pada tahun sesudahnya. Kepala dinas menyimpulkan bahwa lampu penerangan baru itulah yang menurunkan kecelakaan pada malam hari.","p":"Pernyataan berikut yang paling memperkuat kesimpulan tersebut adalah …","o":{"A":"Jumlah kendaraan yang melintas di jalan itu pada malam hari sama besar pada kedua tahun tersebut.","B":"Lampu penerangan baru itu membutuhkan anggaran lebih besar daripada lampu yang lama.","C":"Kecelakaan pada malam hari di jalan itu memang berkurang setelah lampu baru dipasang.","D":"Jalan Lingkar Timur merupakan jalur yang paling sering dilalui truk pengangkut barang.","E":"Pada periode yang sama, kecelakaan pada siang hari di jalan itu juga turun dengan jumlah yang hampir sama."}},{"s":"TIU","t":"Anggap semua premis berikut benar.<br>P1: Semua penyelam tim SAR adalah peserta yang telah lulus uji renang 400 meter.<br>P2: Tidak ada peserta yang lulus uji renang 400 meter yang berusia di bawah 18 tahun.","p":"Kesimpulan yang pasti benar adalah …","o":{"A":"Semua peserta yang lulus uji renang 400 meter adalah penyelam tim SAR.","B":"Sebagian penyelam tim SAR berusia di bawah 18 tahun.","C":"Semua orang yang berusia 18 tahun ke atas adalah penyelam tim SAR.","D":"Tidak ada penyelam tim SAR yang berusia di bawah 18 tahun.","E":"Tidak ada peserta berusia di bawah 18 tahun yang mengikuti uji renang 400 meter."}},{"s":"TIU","t":"Sebuah sekolah membuka kelas daring pada malam hari untuk siswa kelas XII. Satu semester kemudian, rata-rata nilai ujian matematika siswa kelas XII naik dari 68 menjadi 79. Kepala sekolah menyimpulkan bahwa kelas daring malam itulah yang menaikkan nilai siswa.","p":"Pernyataan berikut yang paling memperlemah kesimpulan tersebut adalah …","o":{"A":"Sebagian besar siswa kelas XII mengikuti kelas daring malam itu secara rutin.","B":"Nilai ujian matematika siswa kelas XII naik setelah kelas daring malam dibuka.","C":"Kelas daring malam juga dibuka untuk mata pelajaran bahasa Inggris.","D":"Beberapa orang tua mengeluhkan jadwal kelas daring malam yang berakhir terlalu larut bagi anak mereka.","E":"Pada semester yang sama, soal ujian matematika diganti dengan soal yang lebih mudah."}},{"s":"TIU","t":"Anggap semua premis berikut benar.<br>P1: Jika gudang logistik dibuka, relawan dapat mengambil terpal.<br>P2: Jika relawan dapat mengambil terpal, tenda darurat berdiri sebelum malam.<br>P3: Tenda darurat tidak berdiri sebelum malam.","p":"Kesimpulan yang pasti benar adalah …","o":{"A":"Gudang logistik dibuka, tetapi persediaan terpal sudah habis.","B":"Gudang logistik tidak dibuka.","C":"Relawan dapat mengambil terpal.","D":"Relawan mungkin mengambil terpal dari posko lain.","E":"Tenda darurat berdiri setelah malam tiba."}},{"s":"TIU","t":"HIGROMETER : KELEMBAPAN = … : …","p":"Pasangan kata yang tepat untuk melengkapi analogi tersebut adalah …","o":{"A":"BAROMETER : CUACA","B":"TERMOMETER : DEMAM","C":"SUHU : TERMOMETER","D":"MIKROSKOP : SEL DARAH","E":"AMPEREMETER : KUAT ARUS"}},{"s":"TIU","t":"Kaktus memiliki daun yang berubah bentuk menjadi duri untuk mengurangi penguapan air.","p":"Hubungan antara ciri tubuh dan tujuannya yang sama dengan pernyataan tersebut ditunjukkan oleh …","o":{"A":"Unta memiliki ginjal yang menghasilkan urin sangat pekat untuk menghemat cairan tubuhnya.","B":"Landak memiliki duri tajam di sepanjang punggungnya untuk melindungi diri dari serangan pemangsa.","C":"Bunga bangkai mengeluarkan bau busuk yang menyengat untuk menarik serangga penyerbuk.","D":"Kura-kura memiliki tempurung yang keras untuk melindungi tubuhnya dari serangan.","E":"Burung pelikan memiliki kantong kulit di bawah paruhnya untuk menyendok ikan dari air."}},{"s":"TIU","t":"Nilai yang paling mendekati hasil 4.987 × 0,198 + √3.610 adalah …","o":{"A":"950","B":"1.005","C":"1.045","D":"1.085","E":"1.175"}},{"s":"TIU","t":"Perhatikan tabel berikut. Nilai suku ke-30 adalah …","o":{"A":"1.714","B":"2.554","C":"2.700","D":"2.732","E":"2.854"}},{"s":"TIU","t":"Perhatikan pola bilangan pada tabel berikut. Pasangan nilai X dan Y yang tepat adalah …","o":{"A":"20 dan 12","B":"28 dan 20","C":"40 dan 16","D":"20 dan 8","E":"28 dan 12"}},{"s":"TIU","t":"Perhatikan pola bilangan pada tabel berikut. Nilai X yang tepat adalah …","o":{"A":"−18","B":"−10","C":"14","D":"16","E":"18"}},{"s":"TIU","t":"Pasangan pembagian berikut yang bernilai sama adalah …","o":{"A":"7,2 ÷ 0,6 dan 84 ÷ 7","B":"4,8 ÷ 0,4 dan 66 ÷ 6","C":"9,6 ÷ 0,8 dan 1,3 ÷ 0,1","D":"8,4 ÷ 0,7 dan 1,2 ÷ 0,01","E":"6,3 ÷ 0,7 dan 0,9 ÷ 0,01"}},{"s":"TIU","t":"Pasangan perkalian berikut yang bernilai sama adalah …","o":{"A":"28 × 330 dan 38 × 230","B":"48 × 60 dan 32 × 85","C":"72 × 40 dan 54 × 52","D":"26 × 450 dan 45 × 270","E":"45 × 64 dan 36 × 80"}},{"s":"TIU","t":"Pasangan berikut yang <b>TIDAK</b> bernilai sama adalah …","o":{"A":"(36 ÷ 4) × 7 dan (9 × 8) − 9","B":"(72 ÷ 8) + (6 × 5) dan (13 × 3)","C":"(84 ÷ 7) + (5 × 3) dan (125 ÷ 5) + 4","D":"(15 × 6) − (48 ÷ 4) dan (26 × 3)","E":"(144 ÷ 12) × (3 + 4) dan (7 × 14) − 14"}},{"s":"TIU","t":"Tangki air sebuah truk pemadam kebakaran terisi 10% dari kapasitasnya. Setelah ditambah 3.000 liter air, tangki terisi 60% dari kapasitasnya. Kapasitas penuh tangki tersebut adalah …","o":{"A":"5.000 liter","B":"6.000 liter","C":"6.600 liter","D":"7.200 liter","E":"30.000 liter"}},{"s":"TIU","t":"Sebuah kolam benih ikan dapat diisi penuh oleh keran P dalam 4 jam dan oleh keran Q dalam 12 jam. Keran pembuang R dapat mengosongkan kolam yang penuh dalam 6 jam. Mula-mula kolam kosong, lalu keran P dan Q dibuka bersamaan. Satu jam kemudian keran R juga dibuka, dan ketiganya tetap terbuka. Kolam penuh setelah … sejak keran P dan Q dibuka.","o":{"A":"2 jam 20 menit","B":"3 jam","C":"4 jam","D":"5 jam","E":"6 jam"}},{"s":"TIU","t":"Di sebuah toko alat tulis, setiap map dijual dengan harga yang sama dan setiap spidol juga dijual dengan harga yang sama. Berapa harga 5 map dan 5 spidol?","o":{"A":"Pernyataan (1) SAJA cukup untuk menjawab pertanyaan, tetapi pernyataan (2) SAJA tidak cukup.","B":"Pernyataan (2) SAJA cukup untuk menjawab pertanyaan, tetapi pernyataan (1) SAJA tidak cukup.","C":"Pernyataan (1) dan (2) BERSAMA-SAMA cukup untuk menjawab pertanyaan, tetapi satu pernyataan SAJA tidak cukup.","D":"Pernyataan (1) SAJA cukup DAN pernyataan (2) SAJA cukup untuk menjawab pertanyaan.","E":"Pernyataan (1) dan (2) BERSAMA-SAMA tidak cukup untuk menjawab pertanyaan."},"r":["Harga 2 map dan 2 spidol adalah Rp18.000.","Harga satu map Rp3.000 lebih mahal daripada harga satu spidol."]},{"s":"TIU","t":"Sebuah truk BPBD dengan batas muatan 5.000 kg akan mengangkut karung beras bantuan dalam satu kali jalan. Apakah seluruh karung dapat diangkut tanpa melebihi batas muatan truk?","o":{"A":"Pernyataan (1) SAJA cukup untuk menjawab pertanyaan, tetapi pernyataan (2) SAJA tidak cukup.","B":"Pernyataan (2) SAJA cukup untuk menjawab pertanyaan, tetapi pernyataan (1) SAJA tidak cukup.","C":"Pernyataan (1) dan (2) BERSAMA-SAMA cukup untuk menjawab pertanyaan, tetapi satu pernyataan SAJA tidak cukup.","D":"Pernyataan (1) SAJA cukup DAN pernyataan (2) SAJA cukup untuk menjawab pertanyaan.","E":"Pernyataan (1) dan (2) BERSAMA-SAMA tidak cukup untuk menjawab pertanyaan."},"r":["Jumlah karung beras yang akan diangkut adalah 110 karung.","Karung terberat beratnya 48 kg dan karung teringan beratnya 40 kg."]},{"s":"TIU","t":"Sebuah konveksi menerima satu pesanan seragam dan menugaskan 6 penjahit untuk mengerjakannya. Semua penjahit di konveksi itu bekerja dengan kecepatan yang sama. Apakah pesanan tersebut selesai dalam waktu paling lama 4 hari?","o":{"A":"Pernyataan (1) SAJA cukup untuk menjawab pertanyaan, tetapi pernyataan (2) SAJA tidak cukup.","B":"Pernyataan (2) SAJA cukup untuk menjawab pertanyaan, tetapi pernyataan (1) SAJA tidak cukup.","C":"Pernyataan (1) dan (2) BERSAMA-SAMA cukup untuk menjawab pertanyaan, tetapi satu pernyataan SAJA tidak cukup.","D":"Pernyataan (1) SAJA cukup DAN pernyataan (2) SAJA cukup untuk menjawab pertanyaan.","E":"Pernyataan (1) dan (2) BERSAMA-SAMA tidak cukup untuk menjawab pertanyaan."},"r":["10 penjahit konveksi itu dapat menyelesaikan pesanan yang sama dalam 3 hari.","Setiap penjahit menyelesaikan 12 seragam per hari."]},{"s":"TIU","t":"Seleksi tahap akhir diikuti 84 peserta yang terdiri atas peserta putra dan peserta putri. Berapa banyak peserta putri?","o":{"A":"Pernyataan (1) SAJA cukup untuk menjawab pertanyaan, tetapi pernyataan (2) SAJA tidak cukup.","B":"Pernyataan (2) SAJA cukup untuk menjawab pertanyaan, tetapi pernyataan (1) SAJA tidak cukup.","C":"Pernyataan (1) dan (2) BERSAMA-SAMA cukup untuk menjawab pertanyaan, tetapi satu pernyataan SAJA tidak cukup.","D":"Pernyataan (1) SAJA cukup DAN pernyataan (2) SAJA cukup untuk menjawab pertanyaan.","E":"Pernyataan (1) dan (2) BERSAMA-SAMA tidak cukup untuk menjawab pertanyaan."},"r":["Perbandingan banyak peserta putra dan putri adalah 4 : 3.","Banyak peserta putra 12 orang lebih banyak daripada peserta putri."]},{"s":"TIU","t":"Berapa harga satu kilogram cabai pada awal bulan?","o":{"A":"Pernyataan (1) SAJA cukup untuk menjawab pertanyaan, tetapi pernyataan (2) SAJA tidak cukup.","B":"Pernyataan (2) SAJA cukup untuk menjawab pertanyaan, tetapi pernyataan (1) SAJA tidak cukup.","C":"Pernyataan (1) dan (2) BERSAMA-SAMA cukup untuk menjawab pertanyaan, tetapi satu pernyataan SAJA tidak cukup.","D":"Pernyataan (1) SAJA cukup DAN pernyataan (2) SAJA cukup untuk menjawab pertanyaan.","E":"Pernyataan (1) dan (2) BERSAMA-SAMA tidak cukup untuk menjawab pertanyaan."},"r":["Pada pertengahan bulan, harga cabai naik 15% dari harga awal bulan.","Pada akhir bulan, harga cabai Rp55.000 per kilogram, yaitu 25% lebih tinggi daripada harga awal bulan."]},{"s":"TIU","t":"<i>n</i> adalah bilangan bulat positif. Apakah <i>n</i> habis dibagi 12?","o":{"A":"Pernyataan (1) SAJA cukup untuk menjawab pertanyaan, tetapi pernyataan (2) SAJA tidak cukup.","B":"Pernyataan (2) SAJA cukup untuk menjawab pertanyaan, tetapi pernyataan (1) SAJA tidak cukup.","C":"Pernyataan (1) dan (2) BERSAMA-SAMA cukup untuk menjawab pertanyaan, tetapi satu pernyataan SAJA tidak cukup.","D":"Pernyataan (1) SAJA cukup DAN pernyataan (2) SAJA cukup untuk menjawab pertanyaan.","E":"Pernyataan (1) dan (2) BERSAMA-SAMA tidak cukup untuk menjawab pertanyaan."},"r":["<i>n</i> habis dibagi 4.","<i>n</i> habis dibagi 6."]},{"s":"TIU","t":"Kelas XI-B memiliki dua kegiatan ekstrakurikuler, yaitu paduan suara dan basket. Setiap siswa boleh mengikuti salah satu kegiatan, keduanya, atau tidak mengikuti keduanya. Berapa banyak siswa yang mengikuti paduan suara sekaligus basket?","o":{"A":"Pernyataan (1) SAJA cukup untuk menjawab pertanyaan, tetapi pernyataan (2) SAJA tidak cukup.","B":"Pernyataan (2) SAJA cukup untuk menjawab pertanyaan, tetapi pernyataan (1) SAJA tidak cukup.","C":"Pernyataan (1) dan (2) BERSAMA-SAMA cukup untuk menjawab pertanyaan, tetapi satu pernyataan SAJA tidak cukup.","D":"Pernyataan (1) SAJA cukup DAN pernyataan (2) SAJA cukup untuk menjawab pertanyaan.","E":"Pernyataan (1) dan (2) BERSAMA-SAMA tidak cukup untuk menjawab pertanyaan."},"r":["Sebanyak 18 siswa mengikuti paduan suara dan 15 siswa mengikuti basket.","Kelas XI-B terdiri atas 30 siswa."]},{"s":"TIU","t":"Lima regu siaga bencana, yaitu Anggrek, Bakung, Cempaka, Dahlia, dan Kenanga, mempresentasikan rencana kerja pada hari Senin sampai Jumat. Setiap hari hanya satu regu yang tampil, dan setiap regu membawakan satu topik yang berbeda: banjir, gempa, kebakaran, longsor, atau puting beliung. Ketentuannya sebagai berikut.","p":"Pernyataan berikut yang pasti benar adalah …","o":{"A":"Bakung tampil pada hari Kamis.","B":"Dahlia membawakan topik banjir.","C":"Kenanga tampil pada hari Senin.","D":"Cempaka membawakan topik gempa.","E":"Anggrek membawakan topik kebakaran."}},{"s":"TIU","t":"Enam petugas piket, yaitu Fajar, Gita, Hasan, Indah, Joko, dan Lina, duduk mengelilingi sebuah meja bundar dengan enam kursi berjarak sama. Semua petugas duduk menghadap ke tengah meja. Ketentuannya sebagai berikut.","p":"Petugas yang duduk tepat di hadapan Hasan adalah …","o":{"A":"Fajar","B":"Lina","C":"Gita","D":"Indah","E":"Joko"}},{"s":"TIU","t":"Enam kapal, yaitu Kapal P, Q, R, S, T, dan U, tiba di sebuah pelabuhan pada hari yang sama secara bergantian, dan tidak ada dua kapal yang tiba bersamaan. Ketentuannya sebagai berikut.","p":"Pernyataan berikut yang pasti benar adalah …","o":{"A":"Kapal Q tiba kedua.","B":"Kapal R tiba sebelum Kapal Q.","C":"Kapal T tiba kelima.","D":"Kapal U tiba paling akhir.","E":"Kapal S tiba ketiga."}},{"s":"TIU","t":"Panitia pelatihan memesan paling sedikit 130 nasi kotak dari sebuah katering. Katering hanya menjual nasi kotak dalam paket berikut.","p":"Biaya paling sedikit yang harus dikeluarkan panitia adalah …","o":{"A":"Rp1.980.000","B":"Rp2.080.000","C":"Rp2.195.000","D":"Rp2.320.000","E":"Rp2.400.000"}},{"s":"TIU","t":"Perhatikan urutan gambar berikut.","p":"Gambar manakah yang tepat untuk mengganti tanda tanya?","o":{"A":"assets/tiu-p1/TIU-P1-57-A.svg","B":"assets/tiu-p1/TIU-P1-57-B.svg","C":"assets/tiu-p1/TIU-P1-57-C.svg","D":"assets/tiu-p1/TIU-P1-57-D.svg","E":"assets/tiu-p1/TIU-P1-57-E.svg"},"g":"assets/tiu-p1/TIU-P1-57.svg","og":1},{"s":"TIU","t":"Perhatikan urutan gambar berikut.","p":"Gambar manakah yang tepat untuk mengganti tanda tanya?","o":{"A":"assets/tiu-p1/TIU-P1-58-A.svg","B":"assets/tiu-p1/TIU-P1-58-B.svg","C":"assets/tiu-p1/TIU-P1-58-C.svg","D":"assets/tiu-p1/TIU-P1-58-D.svg","E":"assets/tiu-p1/TIU-P1-58-E.svg"},"g":"assets/tiu-p1/TIU-P1-58.svg","og":1},{"s":"TIU","t":"Perhatikan hubungan gambar berikut.","p":"Gambar manakah yang tepat untuk mengganti tanda tanya?","o":{"A":"assets/tiu-p1/TIU-P1-59-A.svg","B":"assets/tiu-p1/TIU-P1-59-B.svg","C":"assets/tiu-p1/TIU-P1-59-C.svg","D":"assets/tiu-p1/TIU-P1-59-D.svg","E":"assets/tiu-p1/TIU-P1-59-E.svg"},"g":"assets/tiu-p1/TIU-P1-59.svg","og":1},{"s":"TIU","t":"Perhatikan hubungan gambar berikut.","p":"Gambar manakah yang tepat untuk mengganti tanda tanya?","o":{"A":"assets/tiu-p1/TIU-P1-60-A.svg","B":"assets/tiu-p1/TIU-P1-60-B.svg","C":"assets/tiu-p1/TIU-P1-60-C.svg","D":"assets/tiu-p1/TIU-P1-60-D.svg","E":"assets/tiu-p1/TIU-P1-60-E.svg"},"g":"assets/tiu-p1/TIU-P1-60.svg","og":1},{"s":"TIU","t":"Perhatikan kelima gambar berikut.","p":"Gambar manakah yang berbeda dari yang lain?","o":{"A":"assets/tiu-p1/TIU-P1-61-A.svg","B":"assets/tiu-p1/TIU-P1-61-B.svg","C":"assets/tiu-p1/TIU-P1-61-C.svg","D":"assets/tiu-p1/TIU-P1-61-D.svg","E":"assets/tiu-p1/TIU-P1-61-E.svg"},"og":1},{"s":"TIU","t":"Perhatikan kelima gambar berikut.","p":"Gambar manakah yang berbeda dari yang lain?","o":{"A":"assets/tiu-p1/TIU-P1-62-A.svg","B":"assets/tiu-p1/TIU-P1-62-B.svg","C":"assets/tiu-p1/TIU-P1-62-C.svg","D":"assets/tiu-p1/TIU-P1-62-D.svg","E":"assets/tiu-p1/TIU-P1-62-E.svg"},"og":1},{"s":"TIU","t":"Perhatikan pola gambar pada matriks berikut.","p":"Gambar manakah yang tepat untuk mengganti tanda tanya?","o":{"A":"assets/tiu-p1/TIU-P1-63-A.svg","B":"assets/tiu-p1/TIU-P1-63-B.svg","C":"assets/tiu-p1/TIU-P1-63-C.svg","D":"assets/tiu-p1/TIU-P1-63-D.svg","E":"assets/tiu-p1/TIU-P1-63-E.svg"},"g":"assets/tiu-p1/TIU-P1-63.svg","og":1},{"s":"TIU","t":"Perhatikan pola gambar pada matriks berikut.","p":"Gambar manakah yang tepat untuk mengganti tanda tanya?","o":{"A":"assets/tiu-p1/TIU-P1-64-A.svg","B":"assets/tiu-p1/TIU-P1-64-B.svg","C":"assets/tiu-p1/TIU-P1-64-C.svg","D":"assets/tiu-p1/TIU-P1-64-D.svg","E":"assets/tiu-p1/TIU-P1-64-E.svg"},"g":"assets/tiu-p1/TIU-P1-64.svg","og":1},{"s":"TIU","t":"Perhatikan pola gambar pada matriks berikut.","p":"Gambar manakah yang tepat untuk mengganti tanda tanya?","o":{"A":"assets/tiu-p1/TIU-P1-65-A.svg","B":"assets/tiu-p1/TIU-P1-65-B.svg","C":"assets/tiu-p1/TIU-P1-65-C.svg","D":"assets/tiu-p1/TIU-P1-65-D.svg","E":"assets/tiu-p1/TIU-P1-65-E.svg"},"g":"assets/tiu-p1/TIU-P1-65.svg","og":1},{"s":"TKP","t":"Sebagai operator data SMA, Anda melihat wali kelas mengetik ulang nilai rapor satu per satu sampai larut, dan tetap ada yang salah ketik. Aplikasi rapor punya fitur unggah dari templat, tetapi wali kelas khawatir nilai sekelas bisa salah masuk. Langkah pertama yang Anda ambil adalah&hellip;","o":{"A":"Mencoba fitur unggah khusus kelas yang sering salah ketik, lalu mengecek hasilnya.","B":"Meminta siswa pengurus kelas membantu mengetik nilai agar wali kelas cepat selesai.","C":"Mengikuti kebiasaan lama karena wali kelas lebih nyaman mengetik nilai sendiri.","D":"Menunda fitur unggah sampai semester depan, rapor kali ini tetap diketik manual.","E":"Menguji fitur unggah di satu kelas, lalu memperluasnya setelah hasilnya dicocokkan."},"a":"TIK"},{"s":"TKP","t":"Seorang warga minta salinan arsip tanah lama untuk sidang lusa, padahal pencarian biasanya tiga hari kerja sesuai antrean yang Anda atur. Ia hanya menyebut jadwal sidangnya secara lisan, dan dua pemohon lain juga bertenggat minggu ini. Sikap Anda adalah&hellip;","o":{"A":"Meminta surat panggilan sidangnya, lalu mendahulukan arsip warga itu hari ini.","B":"Memproses permohonannya sesuai urutan antrean, dengan waktu standar tiga hari kerja.","C":"Meminta bukti tenggat tiap pemohon mendesak, lalu mendahulukan yang paling dekat.","D":"Menampung permohonannya untuk dibahas di rapat evaluasi layanan bulan depan.","E":"Mendahulukan siapa pun yang mengaku punya tenggat dekat, mulai dari warga ini."},"a":"Pelayanan Publik"},{"s":"TKP","t":"Sebagai staf akademik, Anda harus mengirim rekap kehadiran taruna ke bagian pengasuhan siang ini, dan izin bermalam akhir pekan ditetapkan dari rekap itu. Mesin presensi kosong untuk satu kelas, padahal dosennya mengisi daftar hadir manual dan sebentar lagi selesai mengajar. Langkah paling tepat adalah&hellip;","o":{"A":"Meminta daftar hadir manual dari dosen itu, lalu melengkapi data sebelum dikirim.","B":"Menunggu mesin presensi diperbaiki dulu, baru rekapnya dikirim ke bagian pengasuhan.","C":"Mengikuti saran rekan senior agar rekap dikirim sesuai data mesin saja.","D":"Mengirim rekap tepat waktu, lalu menyusulkan daftar hadir kelas itu dari dosennya.","E":"Meminta seluruh dosen menandatangani daftar hadir manual, lalu menyusun rekap dari awal."},"a":"Profesionalisme"},{"s":"TKP","t":"Menjelang Natal, hampir semua petugas piket terminal yang Anda koordinasikan dibutuhkan, dan rekan-rekan mengusulkan dua petugas yang merayakan Natal diliburkan sepekan. Keduanya hanya butuh libur malam dan hari Natal, sedangkan beberapa bulan lagi giliran rekan lain merayakan Idulfitri. Apa respons Anda?","o":{"A":"Mengambil sendiri seluruh piket malam Natal agar tidak ada rekan yang dirugikan.","B":"Menanyakan kebutuhan tiap petugas di hari besarnya sebagai dasar tukar piket.","C":"Meliburkan keduanya malam dan hari Natal, lalu meminta rekan lain mengisi piketnya.","D":"Menyetujui usul mayoritas rekan untuk meliburkan keduanya sepekan demi meredakan suasana.","E":"Menetapkan tukar piket di hari besar tiap agama, dengan jatah libur sepekan."},"a":"Sosial Budaya"},{"s":"TKP","t":"Rekan senior di loket pajak sebelah Anda menerima berkas keberatan tanpa tanda terima bernomor agar antrean cepat, padahal SOP mewajibkannya, dan ia melakukannya sejak Senin. Tadi pagi Anda menyinggungnya lewat candaan, tetapi tak digubris, dan tiga pemohonnya masih menunggu. Apa yang Anda lakukan?","o":{"A":"Menyinggungnya lagi lewat candaan ringan saat jeda, supaya rekan tidak tersinggung.","B":"Memakai juga cara cepat rekan itu agar antrean jam sibuk tetap lancar.","C":"Mengajak rekan menerbitkan tanda terima tertunda, lalu menyepakati cara mempercepat antrean.","D":"Menerbitkan tanda terima ketiga berkas tadi, lalu meminta rekan kembali mengikuti SOP.","E":"Menegur rekan secara empat mata, lalu menyepakati cara mempercepat antrean mulai besok."},"a":"Profesionalisme"},{"s":"TKP","t":"Sebagai petugas verifikasi di dinas pertanian, Anda belum mengecek enam dari puluhan nama penerima bantuan benih ke lapangan, sehingga benihnya tertahan sesuai aturan. Masa tanam mulai sepuluh hari lagi, sedangkan pengecekan lapangan biasanya selesai dalam tiga hari. Langkah paling tepat adalah&hellip;","o":{"A":"Menyarankan keenam petani memakai benih sisa musim lalu milik kelompoknya.","B":"Menelepon keenam petani itu untuk memastikan datanya, agar benih cepat tersalur.","C":"Mencoret keenam nama, lalu meminta kelompok mengajukan ulang musim tanam depan.","D":"Meminta ketua kelompok tani menjamin keenam nama itu lewat surat pernyataan.","E":"Mendatangi sendiri lahan keenam petani itu pekan ini untuk verifikasi."},"a":"Pelayanan Publik"},{"s":"TKP","t":"Selama musim ujian, pelajar menandai meja ruang baca dengan tas lalu pergi berjam-jam, sehingga lansia dan peneliti sering tak kebagian tempat. Anda koordinator ruang baca yang berwenang mengatur tata tertib, dan penertiban saat ada keluhan tak bertahan begitu petugas pergi. Langkah pertama yang Anda ambil adalah&hellip;","o":{"A":"Menyediakan beberapa meja khusus lansia dan peneliti selama musim ujian ini.","B":"Memberlakukan giliran paling lama tiga jam per meja saat ruang baca penuh.","C":"Mengizinkan pelajar menandai kursi selama musim ujian, yang lain diminta datang pagi.","D":"Menertibkan meja bertanda tas setiap kali ada pengunjung yang mengeluh lagi.","E":"Mempersilakan pengunjung mengatur kursi sendiri sesuai kesepakatan di antara mereka."},"a":"Pelayanan Publik"},{"s":"TKP","t":"Anda staf keuangan kecamatan yang baru ditugasi menyusun laporan dana kelurahan dengan format baru dari kabupaten, tenggatnya tiga hari lagi. Staf yang dulu menyusunnya sudah dimutasi, tetapi masih bisa ditelepon, dan laporan ini wajib dibuat setiap triwulan. Tindakan paling tepat adalah&hellip;","o":{"A":"Meminta staf lama membimbing lewat telepon, lalu mencatatnya jadi panduan seksi.","B":"Meminta atasan mengalihkan laporan itu ke staf lain sampai Anda ikut pelatihan.","C":"Mempelajari sendiri format dari kabupaten, lalu langsung mengirim laporannya sebelum tenggat.","D":"Meminta staf yang dimutasi mengerjakan bagian format baru, sisanya Anda selesaikan.","E":"Mengerjakan seluruh laporan seorang diri tanpa mau dibantu rekan seksi."},"a":"Profesionalisme"},{"s":"TKP","t":"Saat apel pagi yang Anda pimpin sebagai kepala regu penguji kendaraan, seorang penguji senior berkata sambil tertawa bahwa pemilik kendaraan dari satu suku yang suka membantah \"dipersulit ramai-ramai saja, tidak usah pakai aturan\". Beberapa penguji muda ikut tertawa. Sikap Anda adalah&hellip;","o":{"A":"Melaporkan ucapan rekan itu ke kepala balai agar beliau menegurnya secara resmi.","B":"Menganggapnya candaan senior agar apel tetap cair, lalu mengingatkannya secara pribadi nanti.","C":"Menegur ucapan itu di depan apel, dengan penegasan aturan berlaku sama.","D":"Menyerahkan pada penguji muda untuk menilai sendiri sikap mana yang pantas ditiru.","E":"Mengakhiri apel dengan tenang, lalu menegur rekan empat mata atas sikap bencinya."},"a":"Anti Radikalisme"},{"s":"TKP","t":"Sebagai penanggung jawab farmasi puskesmas, Anda didatangi seorang ibu karena label sirup anaknya tertulis 3 &times; 2 sendok, padahal resepnya 3 &times; 1. Label itu ditulis rekan yang yakin sudah teliti, dan ia masih menulis label untuk puluhan resep antrean. Langkah paling tepat adalah&hellip;","o":{"A":"Mengusulkan tambahan tenaga farmasi ke kepala puskesmas agar label tidak menumpuk.","B":"Membetulkan label sirup itu, lalu menunggu antrean sepi baru bicara dengan rekan.","C":"Membetulkan label itu, lalu mencocokkan tiap label dengan resep sebelum diserahkan.","D":"Menulis ulang label sirup itu, lalu meminta rekan lebih cermat menulis berikutnya.","E":"Menyimpulkan rekan kelelahan, lalu mengambil alih sendiri seluruh label resep antrean."},"a":"Profesionalisme"},{"s":"TKP","t":"Belasan keluarga lansia telantar mengeluh mengulang cerita sama karena dikunjungi dua kali sepekan: oleh Anda dari bidang rehabilitasi sosial, dan oleh tim bidang perlindungan sosial. Data tim itu diperbarui pusat bulan lalu, sedangkan data Anda dari pendataan tahun lalu. Respons paling tepat adalah&hellip;","o":{"A":"Melapor ke atasan bahwa bidang sebelah tidak mau berbagi jadwal kunjungan.","B":"Meminta keluarga itu bersabar, jadwal kunjungan bidang Anda tetap jalan seperti biasa.","C":"Menyerahkan daftar kunjungan Anda ke bidang itu sebagai acuan jadwal bersama.","D":"Menyepakati kunjungan gabungan dengan bidang itu, khusus untuk keluarga yang sudah mengeluh.","E":"Mencocokkan daftar keluarga kedua bidang lebih dulu, baru menyusun jadwal kunjungan gabungan."},"a":"Jejaring Kerja"},{"s":"TKP","t":"Sebagai koordinator loket perekaman KTP-el yang berwenang mengatur antrean, Anda menerima lima berkas titipan tetangga rekan sekantor saat kuota hampir habis; katanya mereka sudah ambil nomor, tetapi kartunya tak dibawa. Bulan lalu warga memprotes titipan serupa di loket lain. Apa tindakan paling tepat?","o":{"A":"Memproses kelima titipan lebih dulu, lalu meminta rekan tidak mengulanginya lagi.","B":"Mengembalikan kelima berkas ke rekan itu dengan menunjuk aturan antrean yang tertempel.","C":"Menunggu arahan tertulis kepala dinas soal kelima titipan itu sebelum memprosesnya.","D":"Memasukkan kelima berkas ke antrean umum, dicocokkan dengan nomor seperti lainnya.","E":"Melarang titipan di seluruh loket, lalu memproses kelima berkas atas pengakuan rekan."},"a":"Pelayanan Publik"},{"s":"TKP","t":"Sebagai penyuluh dinas pertanian, Anda merekap proposal kelompok tani bertenggat tiga hari lagi, lalu antivirus memberi peringatan saat flashdisk satu kelompok dicolokkan. Dinas punya pengelola jaringan untuk perangkat bermasalah, dan bulan lalu komputer bidang sebelah tetap tertular walau dibersihkan sendiri. Apa respons Anda?","o":{"A":"Memperbarui antivirus komputer Anda ke versi terbaru, lalu lanjut merekap kelompok lain.","B":"Membawa flashdisk itu ke petugas jaringan, lalu mengabari kelompoknya soal pemeriksaan.","C":"Menanyakan ke rekan satu bidang apakah peringatan semacam itu memang biasa muncul.","D":"Mengembalikan flashdisk itu ke kelompok tani agar mereka bersihkan sendiri dulu.","E":"Menyimpan flashdisk itu terpisah, lalu meminta kelompoknya mengirim ulang berkas lewat surel."},"a":"TIK"},{"s":"TKP","t":"Rekan instruktur las di BLK Anda kerap meninggalkan peserta memakai mesin las tanpa pendamping. Dua kali Anda tegur langsung, ia tetap mengulang, dan kemarin seorang peserta luka bakar ringan. Tugas instruktur diatur kepala seksi; angkatan ini masih berjalan dua bulan. Apa tindakan paling tepat?","o":{"A":"Melaporkan kebiasaan itu ke kepala seksi, lengkap dengan catatan tanggal tiap kejadian.","B":"Mencatat tiap kali rekan pergi, untuk dilaporkan bila ada peserta terluka lagi.","C":"Menjaga hubungan baik dengan rekan, urusan kelas praktik diserahkan pada kesadarannya.","D":"Menegur rekan itu sekali lagi, lebih keras, di depan para peserta las.","E":"Menggantikan rekan mengawasi kelas las setiap kali ia meninggalkan peserta di bengkel."},"a":"Profesionalisme"},{"s":"TKP","t":"Pamflet yang menuding satu kelompok agama sebagai ancaman negara tertempel di ruang ganti perawat, dan fotonya beredar di grup ruangan. Anda kepala ruang yang mengelola papan pengumuman serta grup itu, dan dua perawat dari kelompok tersebut mengaku tidak nyaman. Sikap Anda adalah&hellip;","o":{"A":"Mencopot pamflet, lalu meminta kepala bidang menghapus fotonya dan menemui kedua perawat.","B":"Menahan diri berkomentar di grup, mengingat pamflet itu di luar urusan pelayanan.","C":"Mencari tahu dulu siapa penempelnya, baru meminta fotonya dihapus dari grup.","D":"Mencopot pamflet, menghapus fotonya dari grup, lalu menemui kedua perawat itu.","E":"Menghapus foto pamflet dari grup, tapi pamfletnya dibiarkan agar suasana tak tegang."},"a":"Anti Radikalisme"},{"s":"TKP","t":"Sebagai petugas laboratorium puskesmas, Anda tahu hasil dahak TBC baru jadi tiga hari kerja, tetapi petugas pendaftaran selalu meminta pasien kembali besok. Pekan ini banyak pasien datang sia-sia, dua di antaranya menyewa perahu dari desa seberang. Apa respons Anda?","o":{"A":"Menyepakati dengan pendaftaran agar pasien dari seberang saja yang diberi tanggal ambil.","B":"Menempel pengumuman di depan laboratorium bahwa hasil dahak keluar tiga hari kerja.","C":"Mencatat nomor telepon pasien yang telanjur datang, lalu mengabari begitu hasilnya keluar.","D":"Membiarkan petugas pendaftaran mengurus informasinya sendiri, karena itu bukan tugas laboratorium.","E":"Menyepakati dengan pendaftaran tanggal ambil untuk tiap pasien, lalu mengabari bila mundur."},"a":"Pelayanan Publik"},{"s":"TKP","t":"Sebagai koordinator jaga terminal, Anda mendengar dari sopir bahwa petugas jaga malam sering memutar ceramah yang menyebut pemerintah tidak sah di pengeras suara pos. Sopir itu pun hanya mendengarnya dari rekan sesama pengemudi, dan dinas punya unit pengawasan internal. Apa tindakan paling tepat?","o":{"A":"Mengajak rekan-rekan menjauhi petugas itu sampai kabarnya jelas benar atau tidak.","B":"Memindahkan petugas itu ke giliran siang agar pos malam lebih mudah diawasi.","C":"Melarang pemutaran ceramah apa pun di seluruh pos jaga mulai malam ini.","D":"Meneruskan cerita sopir beserta asal kabarnya ke unit pengawasan internal untuk dicek.","E":"Menegur langsung petugas itu malam ini supaya berhenti memutar ceramah itu."},"a":"Anti Radikalisme"},{"s":"TKP","t":"Anda memandu rapat penerima bantuan pangan desa yang daftarnya disahkan hari ini juga. Seorang kepala dusun bercanda agar keluarga pendatang berbeda keyakinan \"dicoret saja, biar pulang kampung\", dan peserta tertawa. Candaan serupa tadi sudah Anda alihkan. Tindakan paling tepat adalah&hellip;","o":{"A":"Menyela candaan itu: penerima bantuan dinilai dari kelayakan, bukan dari keyakinannya.","B":"Melaporkan ucapan kepala dusun itu ke camat sebagai dugaan ujaran kebencian.","C":"Meminta kepala dusun meralat ucapannya setelah daftar disahkan di rapat itu.","D":"Mengantar sendiri bantuan ke rumah keluarga pendatang agar mereka tak perlu hadir.","E":"Mengalihkan lagi pembicaraan ke kriteria teknis supaya suasana rapat tetap cair."},"a":"Anti Radikalisme"},{"s":"TKP","t":"Kepala bidang penagihan yang sedang di luar kantor minta rekap penunggak pajak berisi NIK dan nomor telepon malam ini, tetapi berkasnya terlalu besar untuk surel dinas. Ia menyarankan aplikasi pesan, padahal data itu hanya boleh dibuka pejabat penagihan. Langkah pertama yang Anda ambil adalah&hellip;","o":{"A":"Menunggu kepala bidang kembali besok pagi untuk mengambil rekap itu sendiri.","B":"Mencoba lagi mengirim rekap lewat surel dinas sampai berkasnya berhasil terkirim.","C":"Mengirim rekap lewat aplikasi pesan, dengan permintaan berkasnya dihapus setelah dibaca.","D":"Menitipkan rekap dalam flashdisk ke staf penagihan yang akan menemuinya malam ini.","E":"Mengunggah rekap ke penyimpanan daring kantor, dengan akses khusus untuk kepala bidang."},"a":"TIK"},{"s":"TKP","t":"Sebagai koordinator pendaftaran puskesmas, Anda melihat beberapa pasien perempuan pulang sebelum diperiksa: setelah antre lama, mereka menolak dokter laki-laki karena keyakinan. Ada dokter perempuan di sif pagi, dan pengumumannya sudah ditempel di ruang tunggu sejak awal bulan. Apa yang Anda lakukan?","o":{"A":"Mengantar pasien yang menolak dokter laki-laki ke ruang dokter perempuan sif pagi.","B":"Menjelaskan antrean berlaku sama bagi siapa pun, silakan datang lagi hari lain.","C":"Mengikuti usul rekan agar pasien yang keberatan dirujuk ke puskesmas lain.","D":"Menempel pengumuman dokter perempuan yang lebih besar di pintu masuk dan loket.","E":"Menanyakan pilihan dokter laki-laki atau perempuan sejak pasien mendaftar di loket."},"a":"Sosial Budaya"},{"s":"TKP","t":"Sejak dua bulan lalu, RSUD mengirim berkas kelahiran ke dinas Anda tiap Jumat agar akta terbit tanpa orang tua datang. Tiga Jumat terakhir, belasan berkas tiba tanpa surat keterangan lahir, dan kekurangan ini belum pernah Anda bicarakan dengan mereka. Sikap Anda adalah&hellip;","o":{"A":"Menyepakati rapat evaluasi bulan depan dengan rekam medis untuk membahas berkas kurang.","B":"Mencatat berkas kurang di register, lalu menunggu rumah sakit sadar sendiri.","C":"Menemui petugas rekam medis, menyepakati daftar periksa, lalu melengkapi berkas tertunda.","D":"Mengembalikan berkas kurang ke rekam medis, lalu menerbitkan akta dari berkas yang lengkap.","E":"Meminta orang tua melengkapi sendiri berkas bayinya agar rumah sakit tidak tersinggung."},"a":"Jejaring Kerja"},{"s":"TKP","t":"Seorang warga keberatan didenda karena bukunya tercatat terlambat, padahal ia yakin sudah memasukkannya ke kotak pengembalian sebelum jatuh tempo. Anda koordinator sirkulasi yang berwenang menghapus denda keliru, dan rekan Anda mencatat isi kotak itu di lembar pengosongan setiap sore. Tindakan paling tepat adalah&hellip;","o":{"A":"Menghapus dendanya saat itu juga karena warga itu yakin sudah tepat waktu.","B":"Melaporkan dugaan salah catat ke petugas TI, lalu meminta warga menunggu hasilnya.","C":"Meminta warga melunasi denda, lalu menuliskan keberatannya di kotak saran.","D":"Mencocokkan pengakuan warga dengan catatan rekan, lalu membatalkan dendanya bila cocok.","E":"Meneruskan keberatan itu ke kepala perpustakaan agar keputusannya punya dasar resmi."},"a":"Pelayanan Publik"},{"s":"TKP","t":"Sebagai staf humas, kemarin Anda mengirim siaran pers capaian imunisasi ke belasan redaksi. Pagi ini bidang program mengabarkan angkanya keliru, dan seorang wartawan sudah menelepon menanyakan selisihnya dengan dasbor resmi. Mengakui salah ke semua redaksi tentu terasa memalukan. Langkah paling tepat adalah&hellip;","o":{"A":"Mengirim angka benar hanya ke redaksi yang lebih dulu bertanya.","B":"Menyiapkan surat jawaban resmi berangka benar untuk wartawan itu, lalu mengarsipkannya.","C":"Mengirim ralat ke seluruh penerima siaran kemarin, lalu menjawab wartawan itu.","D":"Meminta bidang program sendiri yang meluruskan angka itu ke setiap redaksi.","E":"Meminta wartawan menahan beritanya, lalu diam-diam membetulkan angka di laman instansi."},"a":"Profesionalisme"},{"s":"TKP","t":"Di unit pengadaan, Anda menyusun dokumen paket laptop: delapan untuk administrasi, dua untuk penyuntingan video. Spesifikasi dari bidang perencanaan hanya berbunyi \"prosesor setara atau lebih tinggi\", padahal penyedia menyusun penawaran langsung dari dokumen yang diumumkan Senin. Langkah pertama yang Anda ambil adalah&hellip;","o":{"A":"Mengumumkan paket sesuai jadwal, perbedaan tafsir dijawab saat sesi tanya jawab.","B":"Meminta staf baru di unit menafsirkan spesifikasinya dengan merujuk katalog merek.","C":"Menyamakan spesifikasi kesepuluh laptop di kelas menengah agar anggarannya terbagi rata.","D":"Menyalin spesifikasi itu apa adanya agar tidak dianggap mengubah keinginan pihak pemohon.","E":"Meminta bidang perencanaan memperjelas spesifikasi itu hari ini, sebelum paketnya tayang."},"a":"Profesionalisme"},{"s":"TKP","t":"Setiap bulan Anda merekap laporan kunjungan enam relawan sukarela program lansia sebagai dasar usulan bantuan. Bentuk laporannya berbeda-beda, dan dua relawan sudah tiga bulan berturut-turut mengirim sepekan lewat tenggat. Jumat ini ada pertemuan rutin dengan keenam relawan. Apa tindakan paling tepat?","o":{"A":"Memaklumi keterlambatan dan beragamnya laporan sebagai bentuk penghargaan bagi relawan sukarela.","B":"Menagih laporan yang terlambat lewat telepon, lalu menyalin semuanya ke satu format.","C":"Mengirim surat edaran kewajiban lapor tepat waktu ke grup pesan relawan.","D":"Menyepakati format singkat dan tenggat kirim bersama keenam relawan, Jumat ini.","E":"Menyepakati format dan tenggat baru lewat telepon dengan dua relawan yang terlambat."},"a":"Jejaring Kerja"},{"s":"TKP","t":"Dua kali bulan ini puluhan anak menunggu dongeng Sabtu di perpustakaan Anda, dan pendongeng dari komunitas relawan mitra tak kunjung datang. Ketua komunitas sudah meneruskan jadwal, tetapi kedua pendongeng itu ternyata tidak pernah menerima pesannya. Apa yang Anda lakukan?","o":{"A":"Mengganti dongeng dengan pemutaran film kartun tiap kali pendongeng batal datang.","B":"Mengatur bersama ketua komunitas: tiap pendongeng konfirmasi ke Anda sebelum Kamis.","C":"Mengirim surat resmi yang mengingatkan komunitas akan kewajiban hadir dalam nota kesepahaman.","D":"Menyusun jadwal sebulan penuh bersama ketua komunitas agar giliran tiap Sabtu jelas.","E":"Bersiap membacakan dongeng sendiri bila pendongeng komunitas kembali berhalangan datang."},"a":"Jejaring Kerja"},{"s":"TKP","t":"Sejak surel wajib verifikasi dua langkah, tiga staf ruang arsip bawah tanah tak bisa bekerja: kodenya dikirim ke ponsel, padahal di sana tanpa sinyal. Penguat sinyal baru terpasang bulan depan, sementara unit TI Anda masih menyimpan kunci keamanan USB cadangan. Tindakan paling tepat adalah&hellip;","o":{"A":"Mendaftarkan alat verifikasi fisik simpanan unit untuk ketiga staf hari ini.","B":"Meminta kepala instansi membebaskan seluruh staf arsip dari verifikasi dua langkah.","C":"Mengalihkan kode ke ponsel rekan di lantai atas untuk dibacakan lewat telepon.","D":"Menutup akses surel ketiga staf itu sampai ruang arsip mendapat sinyal.","E":"Meminta ketiga staf naik ke lantai atas tiap kali butuh kode verifikasi."},"a":"TIK"},{"s":"TKP","t":"Anda koordinator PKL siswa di enam bengkel mitra yang menampung mereka tanpa bayaran. Dua pemilik bengkel mengeluh lembar penilaian selalu datang mepet, bentuknya berganti tiap semester, dan ada kolom yang tidak mereka pahami. Semester depan ada empat mitra baru. Apa tindakan paling tepat?","o":{"A":"Mendatangi keenam bengkel tiap menjelang batas, lalu membantu pemiliknya mengisi lembar.","B":"Meminta maaf kepada kedua pemilik bengkel dan berjanji kejadian ini tak terulang.","C":"Merumuskan bersama perwakilan bengkel satu format penilaian tetap dan jadwal kirimnya.","D":"Mempercayakan urusan lembar penilaian ke guru pembimbing, merekalah yang paling kenal siswanya.","E":"Merumuskan format tetap bersama perwakilan bengkel begitu semester depan sudah berjalan."},"a":"Jejaring Kerja"},{"s":"TKP","t":"Anda satu-satunya petugas verifikasi surat pindah di kantor kecamatan, dengan puluhan berkas sehari, dan berwenang mengatur jam loket. Senin ini sekretaris camat menugaskan Anda mendata ulang ratusan barang inventaris dalam dua pekan, tanpa tahu verifikasi itu hanya Anda yang mengerjakan. Apa respons Anda?","o":{"A":"Mengumumkan di loket bahwa selama dua pekan hanya berkas mendesak yang dilayani.","B":"Menolak tugas pendataan dan meminta atasan mencari petugas lain demi pelayanan warga.","C":"Mendahulukan pendataan karena perintah atasan, verifikasi surat pindah menunggu sampai selesai.","D":"Menyampaikan beban loket ke sekretaris camat, lalu menyepakati pembagian jam kerjanya.","E":"Mencicil pendataan di sela loket, lalu melapor kalau jadwalnya mulai tertinggal."},"a":"Profesionalisme"},{"s":"TKP","t":"KTP-el pedagang di loket Anda patah, padahal besok pagi ia harus menandatangani pencairan pinjaman di bank. Blanko kosong sampai pekan depan, dan cadangannya disisihkan untuk korban bencana. Surat keterangan pengganti butuh tanda tangan kepala seksi, yang hanya ada sampai sore. Tindakan paling tepat adalah&hellip;","o":{"A":"Melaporkan kekosongan blanko ke kepala dinas agar ada kebijakan khusus warga mendesak.","B":"Memproses surat keterangan pengganti pedagang itu hingga ditandatangani hari ini juga.","C":"Menyiapkan surat keterangan pengganti hari ini, lalu memintakan tanda tangannya besok pagi.","D":"Memeriksa ulang rekaman biometrik pedagang itu di basis data kependudukan lebih dulu.","E":"Memasukkan pedagang itu ke antrean cetak, begitu blanko tiba langsung dibuat."},"a":"Pelayanan Publik"},{"s":"TKP","t":"Anda mengatur rapat penjelasan tender Rabu ini, satu-satunya kesempatan tanya jawab. Seorang calon penyedia minta jadwal digeser karena hari itu Galungan, padahal peserta lain sudah memesan tiket dari luar kota. Sistem tender bisa menyiarkan rapat dan menerima pertanyaan tertulis. Respons paling tepat adalah&hellip;","o":{"A":"Menggeser rapat ke Kamis demi penyedia itu, lalu mengumumkan jadwal barunya.","B":"Meminta penyedia itu membuktikan hari rayanya dulu, khawatir hanya cara mengulur jadwal.","C":"Mengirimkan rekaman rapat kepada penyedia itu agar ia menerima penjelasan yang sama.","D":"Mempertahankan jadwal Rabu apa adanya, mengingat tiap penyedia harus diperlakukan sama.","E":"Menayangkan rapat Rabu secara daring, lalu menampung pertanyaan penyedia sampai Jumat."},"a":"Sosial Budaya"},{"s":"TKP","t":"Berkas kenaikan pangkat guru dari pulau tinggal kurang legalisir fotokopi SK terakhir. SK aslinya di pulau, sedangkan batasnya Jumat dan kapal baru datang Sabtu. Arsip SK ada di bagian kepegawaian Anda, dan kepala subbagian yang berwenang melegalisir sedang di kantor. Apa yang Anda lakukan?","o":{"A":"Menyalin SK guru itu dari arsip, lalu memintakan legalisirnya kepada atasan.","B":"Menyarankan guru itu pulang dulu, lalu menitipkan legalisirnya kepada kerabat di kota.","C":"Mengembalikan berkas karena aturan mewajibkan fotokopi SK sudah dilegalisir saat diserahkan.","D":"Menerima berkas itu sebagai susulan, mengingat SK aslinya baru bisa dibawa Sabtu.","E":"Mencocokkan fotokopi bawaan guru itu dengan arsip, lalu menandatangani legalisirnya."},"a":"Pelayanan Publik"},{"s":"TKP","t":"Anda instruktur kelas otomotif di balai latihan kerja dan penyusun tata tertibnya. Evaluasi tanpa nama menunjukkan tiga peserta luar daerah tertinggal karena rekan kelompok memberi arahan dalam bahasa daerah. Kelompok sering praktik di bengkel tanpa didampingi instruktur. Apa respons Anda?","o":{"A":"Mengajak peserta menyepakati aturan bahasa kelompok pada evaluasi akhir bulan depan.","B":"Membebaskan kelompok memakai bahasa apa pun selama target praktik tercapai.","C":"Mengumumkan besok bahwa arahan praktik wajib berbahasa Indonesia demi peserta luar daerah.","D":"Mengajak peserta menyepakati bahasa Indonesia saat bekerja, lalu memasukkannya ke tata tertib.","E":"Menyarankan ketiga peserta belajar istilah bahasa daerah, lalu membaur dengan kelompoknya."},"a":"Sosial Budaya"},{"s":"TKP","t":"Petugas yang mengaku dari puskesmas datang dengan surat tugas, meminta daftar lansia beserta NIK dan nomor telepon. Anda operator data desa, dan kantor menyimpan nomor resmi puskesmas. Bulan lalu desa tetangga tertipu surat tugas palsu dengan cara serupa. Apa yang Anda lakukan?","o":{"A":"Mengarahkan petugas itu meminta data ke ketua RT, mengingat mereka mengenal warganya.","B":"Memastikan permintaan itu lewat nomor resmi puskesmas, lalu melapor ke kepala desa.","C":"Bertanya kepada rekan sekantor apakah permintaan serupa pernah datang, lalu mengikuti sarannya.","D":"Menyimpan berkas permintaan itu sampai ada arahan tertulis dari pihak kecamatan.","E":"Menelepon nomor di surat tugas itu, lalu menyerahkan daftar bila petugasnya dibenarkan."},"a":"TIK"},{"s":"TKP","t":"Peringatan ketinggian air dari BPBD tempat Anda bertugas dikirim ke grup lima kepala desa di hilir. Banjir pekan lalu, dua desa terlambat mengungsi karena kepala desanya telat membaca pesan, entah kenapa. Anda sendiri hanya piket dua malam sepekan. Tindakan paling tepat adalah&hellip;","o":{"A":"Menelepon kedua kepala desa itu setiap kali peringatan dikirim, hingga mereka membalas.","B":"Menyepakati dengan kelima desa satu petugas penerima peringatan yang wajib segera membalas.","C":"Melanjutkan pengiriman lewat grup yang sama karena kelima desa harus diperlakukan setara.","D":"Mengusulkan camat menerbitkan instruksi agar kedua kepala desa itu rajin membuka grup.","E":"Menegur kedua kepala desa itu di grup karena lalai membaca peringatan banjir."},"a":"Jejaring Kerja"},{"s":"TKP","t":"Sebagai penyuluh baru, Anda menemukan hasil ukur GPS luas tanam tiga desa jauh di bawah angka rekan senior di laporan tim. Laporan itu dikirim Jumat sebagai dasar pembagian pupuk bersubsidi. Rekan senior itu ada di kantor hari ini. Respons paling tepat adalah&hellip;","o":{"A":"Mengirim laporan tepat waktu tanpa mempersoalkan angka rekan, demi menghormati senior.","B":"Membahas selisih ketiga desa dengan rekan senior setelah laporan tim terkirim hari Jumat.","C":"Membahas selisih hasil ukur dengan rekan senior, karena laporan akan dikirim hari Jumat.","D":"Melaporkan angka rekan senior itu ke kepala bidang, lalu meminta laporan ditahan.","E":"Mengirim pesan kepada rekan senior bahwa angka ketiga desa itu tampak keliru."},"a":"Profesionalisme"},{"s":"TKP","t":"Sebagai admin aplikasi surat keterangan daring kecamatan, Anda berwenang mengubah tampilan aplikasi. Sepekan uji coba, puluhan pengajuan warga ditolak karena foto kartu keluarga melebihi 2 MB, padahal bulan depan loket kertas ditutup. Kebanyakan warga mengirim dari rumah. Sikap Anda adalah&hellip;","o":{"A":"Memasang petunjuk batas ukuran dan cara mengecilkan foto di halaman unggah aplikasi.","B":"Membalas pengajuan yang ditolak dengan aturan batas foto, lalu meminta unggah ulang.","C":"Membantu warga yang datang ke kantor kecamatan mengecilkan foto sebelum diunggah.","D":"Mendukung usul staf agar loket kertas tetap dibuka sampai warga terbiasa daring.","E":"Mengarahkan warga yang fotonya ditolak ke jasa pengetikan di luar kantor."},"a":"TIK"},{"s":"TKP","t":"Tiga apel Senin terakhir, seorang rekan di bagian Anda tetap duduk saat Indonesia Raya dinyanyikan. Beberapa pegawai mulai berbisik bahwa ia menolak negara, padahal belum ada yang mengajaknya bicara. Ia sendiri tak pernah menyampaikan pandangan apa pun. Langkah pertama Anda adalah&hellip;","o":{"A":"Menyampaikan sikap rekan itu kepada kepala bagian agar dibina sesuai aturan disiplin.","B":"Menemui rekan itu empat mata untuk menanyakan alasannya tetap duduk saat apel.","C":"Membela rekan itu di depan pegawai lain dan siap ikut menanggung sikapnya.","D":"Menanyakan kepada rekan-rekan lain apakah mereka juga melihat gelagat serupa darinya.","E":"Mengingatkan rekan di depan barisan bahwa pegawai wajib berdiri saat lagu kebangsaan."},"a":"Anti Radikalisme"},{"s":"TKP","t":"Anda staf desa yang mengatur peminjaman balai menurut urutan permohonan. Majelis taklim dan kelompok arisan biasa memesan sebulan sebelumnya, sehingga persekutuan doa keluarga Kristen dan sanggar tari warga pendatang belum sekali pun kebagian tahun ini. Pengurus keduanya mengeluh kepada Anda. Apa tindakan paling tepat?","o":{"A":"Menawarkan kedua kelompok itu jadwal malam hari, saat balai jarang dipesan.","B":"Mempertahankan urutan permohonan karena sebagian besar warga sudah puas dengan cara itu.","C":"Meminta majelis taklim merelakan satu jadwalnya bulan ini demi kedua kelompok itu.","D":"Menyusun bersama para pengurus jadwal bulanan yang memberi giliran tiap kelompok.","E":"Menampung keluhan itu sampai pengurusnya mengajukan keberatan tertulis kepada kepala desa."},"a":"Sosial Budaya"},{"s":"TKP","t":"Unit TI Anda akan memasang pembaruan keamanan server yang mematikan aplikasi layanan enam jam. Vendor menawarkan Sabtu pagi atau sore, yang menurut catatan paling sepi, asal jamnya dikunci Rabu. Bidang perizinan, satu dari tiga pemakainya, biasa menjadwalkan pemohon sepekan sebelumnya. Langkah paling tepat adalah&hellip;","o":{"A":"Mengedarkan dua pilihan jam kepada ketiga bidang untuk dijawab sebelum Rabu.","B":"Mengambil Sabtu pagi tawaran vendor demi menjaga hubungan kerja yang sudah baik.","C":"Memilih Sabtu sore karena menurut catatan, saat itulah aplikasi paling sepi.","D":"Mengabari ketiga bidang begitu jam dikunci Rabu agar mereka menyesuaikan layanannya.","E":"Membagi pemeliharaan menjadi dua jam setiap Sabtu selama tiga pekan berturut-turut."},"a":"Jejaring Kerja"},{"s":"TKP","t":"Anda staf humas pengatur siaran langsung radio soal tarif retribusi. Separuh acara berisi tanya jawab telepon yang hanya boleh dijawab kepala bidang pendapatan. Jadwal rencana kerja humas jatuh pada Jumat Agung, hari ibadah beliau, padahal radio sanggup pekan depan. Sikap Anda adalah&hellip;","o":{"A":"Menyepakati hari siaran pekan depan dengan narasumber, lalu mengabarkannya ke radio.","B":"Merekam wawancara narasumber sehari sebelumnya, demi siaran tetap tayang Jumat itu.","C":"Membiarkan pihak radio memutuskan jadwalnya sendiri karena slot siaran milik mereka.","D":"Berpegang pada jadwal rencana kerja humas dan meminta narasumber menyesuaikan diri.","E":"Meminta staf senior bidang pendapatan menggantikan beliau, karena bahan siarannya sudah tertulis."},"a":"Sosial Budaya"},{"s":"TKP","t":"Pekan lalu rekan senior di tim lapangan BPBD menyodori Anda formulir setia kepada kelompok yang ingin mengganti Pancasila. Anda menolak dan menasihatinya. Kemarin, saat pelatihan relawan, Anda melihat sendiri ia membagikan formulir itu kepada dua relawan muda. Respons paling tepat adalah&hellip;","o":{"A":"Menasihati rekan itu sekali lagi, lalu meminta kedua relawan mengembalikan formulirnya.","B":"Menghormati kebebasan berkeyakinan rekan itu dan membiarkan relawan memutuskan sendiri.","C":"Melaporkan kedua kejadian ke kepala pelaksana BPBD, karena nasihat Anda tak mempan.","D":"Mencatat kedua kejadian dan saksinya, lalu menunggu satu ajakan lagi untuk dilaporkan.","E":"Menjaga hubungan dengan rekan senior itu dengan tidak lagi membahas ajakannya."},"a":"Anti Radikalisme"},{"s":"TKP","t":"Edaran baru mewajibkan pakaian adat setiap Kamis tanpa merinci adat daerah mana. Anda staf kepegawaian yang ditugasi menyusun petunjuk pelaksanaannya, dan enam pegawai asal luar daerah bertanya apakah boleh memakai adat asalnya. Pelanggaran edaran masuk penilaian disiplin. Apa yang Anda lakukan?","o":{"A":"Mengumumkan di grup pegawai bahwa pakaian adat daerah asal boleh dipakai.","B":"Mencantumkan dalam petunjuk pelaksanaan bahwa pakaian adat daerah asal juga diterima.","C":"Memintakan izin tertulis sekretaris daerah khusus bagi keenam pegawai yang bertanya.","D":"Meneruskan pertanyaan itu ke bagian hukum karena menafsirkan edaran adalah tugas mereka.","E":"Mewajibkan adat daerah setempat bagi seluruh pegawai, mengikuti suara terbanyak rapat staf."},"a":"Sosial Budaya"},{"s":"TKP","t":"Sebagai petugas pengaduan RSUD, Anda membaca unggahan keluarga pasien yang dimintai Rp50.000 di kasir rawat jalan agar klaimnya cepat diproses. Unggahan itu tanpa tanggal dan nama petugas, sementara kasir dijaga empat orang bergantian. Setiap pembayaran tercetak di kuitansi bernomor. Respons paling tepat adalah&hellip;","o":{"A":"Meneruskan unggahan itu ke direktur agar keempat petugas kasir segera diperiksa.","B":"Meminta pengunggah menghapus unggahannya lebih dulu agar nama baik rumah sakit terjaga.","C":"Memasang pengumuman larangan pungutan di meja kasir rawat jalan mulai hari ini.","D":"Mengganti uang Rp50.000 itu kepada pengunggah dari dompet pribadi Anda.","E":"Menghubungi pengunggah, meminta waktu kejadian dan nomor kuitansinya untuk pemeriksaan."},"a":"Pelayanan Publik"},{"s":"TKP","t":"Dua rekan meneruskan poster yang menyebut pajak daerah haram karena pemerintah tidak sah ke grup pegawai kantor pajak yang Anda kelola. Dalam sejam, puluhan anggota sudah membacanya. Salah satu pengirim lalu bertanya di bawahnya apakah isinya benar. Langkah paling tepat adalah&hellip;","o":{"A":"Menghapus poster itu dari grup, lalu menyematkan aturan larangan konten serupa.","B":"Membiarkan anggota grup menilai sendiri isi poster sambil menunggu ada yang keberatan.","C":"Meneruskan poster itu ke kepala kantor dan meminta beliau memutuskan langkahnya.","D":"Menghapus poster itu dari grup, lalu mengingatkan kedua pengirimnya secara pribadi.","E":"Menarik poster itu dengan pengumuman bahwa kedua pengirimnya akan dilaporkan ke atasan."},"a":"Anti Radikalisme"}];
